import os

root = "AlgebraicJacobian.lean"

def get_imports(path):
    imps = []
    if not os.path.exists(path):
        return imps
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line.startswith("import "):
                mod = line[len("import "):].strip()
                imps.append(mod)
    return imps

def mod_to_path(mod):
    return mod.replace(".", "/") + ".lean"

visited = set()
stack = [root]
while stack:
    cur = stack.pop()
    if cur in visited:
        continue
    visited.add(cur)
    imps = get_imports(cur)
    for m in imps:
        p = mod_to_path(m)
        if p not in visited:
            stack.append(p)

aj_visited = {v for v in visited if v.startswith("AlgebraicJacobian/")}
print("Total AJ modules reachable:", len(aj_visited))

all_aj = set()
for dirpath, dirs, files in os.walk("AlgebraicJacobian"):
    for f in files:
        if f.endswith(".lean"):
            all_aj.add(os.path.join(dirpath, f))

unreachable = all_aj - aj_visited
print("Total AJ .lean files on disk:", len(all_aj))
print("Unreachable count:", len(unreachable))
